import { aplicarEvento, aoConectar, aoDesconectar, aoVoltarDoFundo, estadoInicial, type EventoEstado } from '../src/core/realtime/estado';
import { LeitorEventos } from '../src/core/realtime/stream';

const sessao = (id: string, sessionRevision: number) => ({ id, name: id, state: 'preparando', competitors: [], sessionRevision }) as never;
const ev = (seq: number, ...sessoes: never[]): EventoEstado => ({ seq, sessoes });

describe('estado em tempo real', () => {
  it('escrita só libera depois do primeiro estado completo', () => {
    let e = aoConectar(estadoInicial);
    expect(e.escritaLiberada).toBe(false);
    e = aplicarEvento(e, ev(1, sessao('a', 1)));
    expect(e.escritaLiberada).toBe(true);
    expect(e.conexao).toBe('INTERNET_SEGURA');
  });

  it('evento repetido ou fora de ordem é ignorado', () => {
    let e = aplicarEvento(aoConectar(estadoInicial), ev(1, sessao('a', 5)));
    const antes = e;
    e = aplicarEvento(e, ev(1, sessao('a', 9)));
    expect(e).toBe(antes);
  });

  it('revisão de uma bateria nunca regride', () => {
    let e = aplicarEvento(aoConectar(estadoInicial), ev(1, sessao('a', 5)));
    e = aplicarEvento(e, ev(2, sessao('a', 3)));
    expect(e.sessoes[0].sessionRevision).toBe(5);
  });

  it('lacuna de sequência pede estado completo e trava a escrita', () => {
    let e = aplicarEvento(aoConectar(estadoInicial), ev(1, sessao('a', 1)));
    e = aplicarEvento(e, ev(5, sessao('a', 2)));
    expect(e.precisaSincronizar).toBe(true);
    expect(e.escritaLiberada).toBe(false);
  });

  it('reconexão recomeça a sequência, mas trava a escrita até o novo estado', () => {
    let e = aplicarEvento(aoConectar(estadoInicial), ev(7, sessao('a', 1)));
    e = aoDesconectar(e);
    expect(e.conexao).toBe('RECONECTANDO');
    expect(e.escritaLiberada).toBe(false);
    e = aoConectar(e);
    expect(e.escritaLiberada).toBe(false);
    e = aplicarEvento(e, ev(1, sessao('a', 2)));
    expect(e.escritaLiberada).toBe(true);
    expect(e.precisaSincronizar).toBe(false);
  });

  it('volta do segundo plano recarrega antes de liberar escrita', () => {
    let e = aplicarEvento(aoConectar(estadoInicial), ev(1, sessao('a', 1)));
    e = aoVoltarDoFundo(e);
    expect(e.escritaLiberada).toBe(false);
    expect(e.precisaSincronizar).toBe(true);
  });
});

describe('leitor do fluxo', () => {
  it('monta eventos em pedaços, ignora batidas e identifica auth-expired', () => {
    const l = new LeitorEventos();
    expect(l.adicionar(': batida\n\nevent: sta')).toEqual([]);
    expect(l.adicionar('te\ndata: {"seq":1,"sessoes":[]}\n\nevent: auth-expired\ndata: {}\n\n')).toEqual([
      { tipo: 'state', dados: { seq: 1, sessoes: [] } }, { tipo: 'auth-expired', dados: {} },
    ]);
  });
  it('JSON quebrado não derruba e pede sincronização', () => {
    expect(new LeitorEventos().adicionar('event: state\ndata: {quebrado\n\n')).toEqual([{ tipo: 'invalido', dados: null }]);
  });
});

describe('correções da revisão: conexão', () => {
  const { conectarFluxo } = require('../src/core/realtime/stream');
  const { baseSegura } = require('../src/core/api/cliente');

  it('volta do fundo também rebaixa a barra', () => {
    const e = aoVoltarDoFundo(aplicarEvento(aoConectar(estadoInicial), ev(1, sessao('a', 1))));
    expect(e.conexao).toBe('RECONECTANDO');
  });
  it('lacuna marca dados desatualizados', () => {
    const e = aplicarEvento(aplicarEvento(aoConectar(estadoInicial), ev(1, sessao('a', 1))), ev(9));
    expect(e.conexao).toBe('SOMENTE_LEITURA_DESATUALIZADA');
  });
  it('fora do desenvolvimento só aceita HTTPS', () => {
    expect(baseSegura('https://a', false)).toBe(true);
    expect(baseSegura('http://a', false)).toBe(false);
    expect(baseSegura('http://127.0.0.1:4799', false)).toBe(true);
    expect(baseSegura('http://127.0.0.1.evil.com', false)).toBe(false);
  });
  it('conexão muda sem dados por 45 s é derrubada', async () => {
    jest.useFakeTimers();
    let abortado = false;
    const f = jest.fn(async (_u: string, init: RequestInit) => ({
      status: 200, ok: true,
      body: { getReader: () => ({ read: () => new Promise((_, rej) => init.signal!.addEventListener('abort', () => { abortado = true; rej(new Error('abort')); })) }) },
    }));
    const avisos = { aoConectar: jest.fn(), aoDesconectar: jest.fn(), aoEvento: jest.fn(), aoSairDoLogin: jest.fn() };
    const c = conectarFluxo('https://x', f, { tokenAtual: async () => ({ accessToken: 'a' }) }, avisos);
    await jest.advanceTimersByTimeAsync(44_000);
    expect(abortado).toBe(false);
    await jest.advanceTimersByTimeAsync(2_000);
    expect(abortado).toBe(true);
    expect(avisos.aoDesconectar).toHaveBeenCalled();
    c.parar();
    jest.useRealTimers();
  });
});
